CREATE TABLE IF NOT EXISTS mailboxes (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, imap_host VARCHAR(255) NOT NULL, imap_port SMALLINT UNSIGNED NOT NULL DEFAULT 993, imap_username VARCHAR(255) NOT NULL, imap_password_env VARCHAR(255) NOT NULL, imap_folder VARCHAR(255) NOT NULL DEFAULT 'INBOX', imap_mark_seen BOOLEAN NOT NULL DEFAULT TRUE, smtp_host VARCHAR(255) NULL, smtp_port SMALLINT UNSIGNED NULL, smtp_username VARCHAR(255) NULL, smtp_password_env VARCHAR(255) NULL, smtp_from VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS distributors (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, sender_policy ENUM('allow_all','whitelist','blacklist','members_only') NOT NULL DEFAULT 'allow_all', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mailbox_distributors (mailbox_id BIGINT UNSIGNED NOT NULL UNIQUE, distributor_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (mailbox_id, distributor_id), CONSTRAINT fk_mailbox_distributor_mailbox FOREIGN KEY (mailbox_id) REFERENCES mailboxes(id) ON DELETE CASCADE, CONSTRAINT fk_mailbox_distributor_distributor FOREIGN KEY (distributor_id) REFERENCES distributors(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS data_sources (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, driver ENUM('postgres','mysql','sqlite') NOT NULL, dsn TEXT NOT NULL, username VARCHAR(255) NULL, password_env VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mailing_lists (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, list_type ENUM('static','database') NOT NULL, datasource_id BIGINT UNSIGNED NULL, recipient_table VARCHAR(255) NULL, email_column VARCHAR(255) NULL, name_column VARCHAR(255) NULL, filter_json JSON NULL, delivery_batch_size INT UNSIGNED NULL, delivery_use_bcc BOOLEAN NULL, delivery_to_header ENUM('from','undisclosed') NULL, delivery_delay_seconds INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_list_datasource FOREIGN KEY (datasource_id) REFERENCES data_sources(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE mailing_lists ADD COLUMN IF NOT EXISTS delivery_batch_size INT UNSIGNED NULL;
ALTER TABLE mailing_lists ADD COLUMN IF NOT EXISTS delivery_use_bcc BOOLEAN NULL;
ALTER TABLE mailing_lists ADD COLUMN IF NOT EXISTS delivery_to_header ENUM('from','undisclosed') NULL;
ALTER TABLE mailing_lists ADD COLUMN IF NOT EXISTS delivery_delay_seconds INT UNSIGNED NULL;
CREATE TABLE IF NOT EXISTS distributor_lists (distributor_id BIGINT UNSIGNED NOT NULL, mailing_list_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (distributor_id, mailing_list_id), CONSTRAINT fk_distributor_list_distributor FOREIGN KEY (distributor_id) REFERENCES distributors(id) ON DELETE CASCADE, CONSTRAINT fk_distributor_list_list FOREIGN KEY (mailing_list_id) REFERENCES mailing_lists(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS distributor_sender_lists (distributor_id BIGINT UNSIGNED NOT NULL, mailing_list_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (distributor_id, mailing_list_id), CONSTRAINT fk_sender_list_distributor FOREIGN KEY (distributor_id) REFERENCES distributors(id) ON DELETE CASCADE, CONSTRAINT fk_sender_list_list FOREIGN KEY (mailing_list_id) REFERENCES mailing_lists(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mailing_list_members (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, mailing_list_id BIGINT UNSIGNED NOT NULL, name VARCHAR(255) NOT NULL, email VARCHAR(320) NOT NULL, receives_mail BOOLEAN NOT NULL DEFAULT TRUE, member_since DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_list_member_email (mailing_list_id, email), CONSTRAINT fk_member_list FOREIGN KEY (mailing_list_id) REFERENCES mailing_lists(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS processed_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, mailbox_id BIGINT UNSIGNED NOT NULL, imap_uid BIGINT UNSIGNED NOT NULL, message_id VARCHAR(998) NULL, subject TEXT NULL, received_at DATETIME NULL, status ENUM('processing','sent','failed','rejected') NOT NULL, attempts INT UNSIGNED NOT NULL DEFAULT 0, error_message TEXT NULL, processed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_message_uid (mailbox_id, imap_uid), KEY idx_processed_messages_status (status), CONSTRAINT fk_processed_mailbox FOREIGN KEY (mailbox_id) REFERENCES mailboxes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
